import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Getting system information ...")
  print(f"\nYou are logged on {os.environ.get('HOST', '')}", flush=True)
  print(" ", flush=True)
  run("system_profiler", "SPSoftwareDataType")

  helpers.print_subheader("\\nAdditionnal information: ")
  run("uname", "-a")
  print("\nUsers logged on: ", flush=True)
  run("w", "-h")
  print("\nCurrent date : ", flush=True)
  run("date")
  print("\nMachine stats : ", flush=True)
  run("uptime")
  print("\nCurrent network location : ", flush=True)
  run("scselect")
  print("\nDNS Configuration: ", flush=True)
  run("scutil", "--dns")

  run("mise", "run", "ips:remoteip")


if __name__ == "__main__":
  main()
